export const creatorSchema = ['id','name','platform','country','language','topic','followers','recentViews','engagement','audienceCountry','fee','goal','contentUrl'];
const names=['Pixel Workshop','Frame by Frame','Budget Respawn','Nordic Loadout','Second Life Setup','FPS Foundry','Cozy Hardware','The Upgrade Bench','Byte Side','Clutch Components','Reboot Room','Silicon Scout','Level Up Lab','Rig Revival','Low Spec Legends','Circuit Stories','Play Again Studio','Desk Quest','Benchmark Club','Afterlife Arcade'];
const topics=['Budget PC builds','PC benchmarking','Refurbished tech','Competitive gaming','PC upgrades'];
export const demoCreators=names.map((name,i)=>({id:`demo-${i+1}`,name,platform:['YouTube','Twitch','TikTok'][i%3],country:['Germany','Finland','Germany','France','Netherlands'][i%5],language:['German','English','German','French','English'][i%5],topic:topics[i%5],followers:18000+i*7400,recentViews:i%6===0?null:12000+i*2300,engagement:i%6===0?null:2.8+(i%5)*0.6,audienceCountry:i%4===0?null:['Germany','Finland','Germany','France','Netherlands'][i%5],fee:i%3===0?null:350+i*70,goal:i%4===0?'sellers':'buyers',contentUrl:null,contentTitle:['Can a budget rig still deliver?','What I measure in a PC test','Giving an older setup a second life','A week with an entry-level gaming PC','When is it time to upgrade?'][i%5],conflict:i%7===0?'Sample disclosure: ongoing relationship with a new-PC retailer. Exclusivity needs checking.':null,source:'Fictional demo profile; all known figures are illustrative.'}));
export const defaultCampaign={name:'More play. Less spend.',goal:'buyers',country:'Germany',language:'German',audience:'Value-conscious gamers, 18+',category:'Refurbished gaming PCs',budget:3000,platform:'All platforms',facts:'Prenew is a European marketplace for buying refurbished gaming PCs and selling old gaming PCs.'};
export function scoreCreator(c,campaign,weights){const factors={content:c.topic==='Competitive gaming'?65:c.topic==='PC benchmarking'?85:95,market:c.audienceCountry===null?null:(c.audienceCountry===campaign.country?100:30),language:c.language===campaign.language?100:20,performance:c.recentViews===null?null:Math.min(100,Math.round(c.recentViews/c.followers*100)),campaign:c.goal===campaign.goal?100:45};let total=0,denom=0;for(const k in factors)if(factors[k]!==null){total+=factors[k]*weights[k];denom+=weights[k]}return {factors,score:denom?Math.round(total/denom):null,known:Object.values(factors).filter(x=>x!==null).length};}
